style.css:
@-moz-document domain("minecraft.net") {
:root {
    --verde-fundo: #0b1e0f; /* verde bem escuro */
    --verde-secundario: #123d1f;
    --verde-bolha: rgba(0, 255, 128, 0.15);
    --verde-borda: rgba(0, 255, 128, 0.3);
    --verde-texto: #a8ffbf;
  }

  body {
    background: var(--verde-fundo) !important;
    color: var(--verde-texto) !important;
    font-family: "Segoe UI", Arial, sans-serif !important;
  }

  /* Efeito de bolhas verdes */
  body::before {
    content: "";
    position: fixed;
    inset: 0;
    pointer-events: none;
    background:
      radial-gradient(circle 80px at 20% 30%, var(--verde-bolha), transparent 70%),
      radial-gradient(circle 100px at 70% 60%, var(--verde-bolha), transparent 70%),
      radial-gradient(circle 60px at 50% 80%, var(--verde-bolha), transparent 80%);
    animation: bolhasVerdes 18s ease-in-out infinite;
    z-index: 0;
  }

  @keyframes bolhasVerdes {
    0%, 100% { background-position: 20% 30%, 70% 60%, 50% 80%; }
    50% { background-position: 25% 35%, 75% 65%, 55% 75%; }
  }

  /* Painéis */
  .card, .container, .section, header, footer {
    background: var(--panel) !important;
    border: 1px solid var(--verde-borda) !important;
    border-radius: 12px !important;
    box-shadow: 0 8px 20px rgba(0, 255, 128, 0.2);
    position: relative;
    z-index: 1;
  }

  /* Botões */
  button, .btn, input[type="submit"] {
    background: linear-gradient(180deg, var(--verde-secundario), var(--verde-fundo)) !important;
    border: 1px solid var(--verde-borda) !important;
    color: var(--verde-texto) !important;
    border-radius: 8px !important;
    padding: 8px 14px !important;
    font-weight: bold !important;
    box-shadow: 0 4px 10px rgba(0, 255, 128, 0.3);
    transition: background 0.3s ease;
  }

  button:hover, .btn:hover, input[type="submit"]:hover {
    background: linear-gradient(180deg, #1e5e33, #0f3a1d) !important;
  }

  /* Links */
  a {
    color: var(--verde-texto) !important;
    text-decoration: none !important;
  }
  a:hover {
    text-decoration: underline !important;
  }
}
